import{_ as t,o as r,c as o,ah as a}from"./chunks/framework.DDXs_i7t.js";const d=JSON.parse('{"title":"Research: Helmut Horten – Armament & Forced Labor","description":"","frontmatter":{},"headers":[],"relativePath":"en/recherche/helmut-horten-ruestung-zwangsarbeit.md","filePath":"en/recherche/helmut-horten-ruestung-zwangsarbeit.md"}'),n={name:"en/recherche/helmut-horten-ruestung-zwangsarbeit.md"};function s(i,e,h,c,m,l){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="research-helmut-horten-–-armament-forced-labor" tabindex="-1">Research: Helmut Horten – Armament &amp; Forced Labor <a class="header-anchor" href="#research-helmut-horten-–-armament-forced-labor" aria-label="Permalink to &quot;Research: Helmut Horten – Armament &amp; Forced Labor&quot;">​</a></h1><p><strong>Beyond the department stores – The darker side of the business empire.</strong></p><p>While Helmut Horten&#39;s rise is often associated primarily with the &quot;Aryanization&quot; of department stores, historical research shows that his activities during the Nazi era were even more deeply intertwined with the regime&#39;s power structures.</p><hr><h2 id="armament-and-war-economy" tabindex="-1">Armament and War Economy <a class="header-anchor" href="#armament-and-war-economy" aria-label="Permalink to &quot;Armament and War Economy&quot;">​</a></h2><p>During World War II, Horten expanded his business activities into the armament sector. As an &quot;opportunistic profiteer&quot; (as described in the Hoeres Report), he used his contacts within the party and state apparatus to secure lucrative supply contracts for the Wehrmacht.</p><h3 id="forced-labor" tabindex="-1">Forced Labor <a class="header-anchor" href="#forced-labor" aria-label="Permalink to &quot;Forced Labor&quot;">​</a></h3><p>There are indications and historical documentation that companies within the Horten sphere of influence made use of forced laborers. The exploitation of people from the occupied territories was a systematic component of the German war economy, from which Horten&#39;s companies also benefited.</p><hr><h2 id="significance-for-the-horten-mystery" tabindex="-1">Significance for &quot;The Horten Mystery&quot; <a class="header-anchor" href="#significance-for-the-horten-mystery" aria-label="Permalink to &quot;Significance for &quot;The Horten Mystery&quot;&quot;">​</a></h2><p>In Part 2 of our mockumentary, we show that the &quot;pointillism of capital&quot; also includes blood-stained dots. The wealth was not only based on the takeover of Jewish businesses but also on the exploitation of labor in the context of the war.</p><ul><li><strong>Aesthetic Motif:</strong> We show the &quot;clean&quot; floors of the department stores, under which the &quot;oily&quot; machines of the war economy are pulsing. The contrast between the luxury of the customers and the suffering of the forced laborers is a central moral weight of the film.</li></ul><hr><p><em>Sources: The Hoeres Report (2022), studies on the economy in National Socialism, and archives on forced labor in the German Reich.</em></p>',14)])])}const f=t(n,[["render",s]]);export{d as __pageData,f as default};
